import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = list(reader)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])

    while len(columns) < width:
        columns.append("column_" + str(len(columns) + 1))

    normalized_rows = []
    for row in rows:
        normalized_rows.append(row + [""] * (width - len(row)))

    return {"columns": columns, "rows": normalized_rows}
